// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        uint256 initialOwnerBalance = c.balanceOf(address(this));
        address attacker = address(0xdead);
        vm.prank(attacker);
        bool succ;
        try c.XBornID() {
            succ = true;
        } catch {
            succ = false;
        }
        assertTrue(c.balanceOf(address(this)) == initialOwnerBalance);
    }
}
